"""CH77: EGVLA1 vs EGVLA2 비교 + FM 헤드가 π0.7과 얼마나 같은가(정직한 대응표). gen_ch77.py가 호출."""
import gen_ch76_viz as V

A, G, R, B, P, MUT = V.A, V.G, V.R, V.B, V.P, V.MUT


def block(tbl, H, st):
    v1 = V.flow([("카메라", MUT), ("OWLv2 + Kosmos-2", R, "두 모델·458M·1277 GFLOPs"), ("bbox + 특징", B), ("MLP 헤드", R, "8-class 이산, 속력 고정"), ("모터", G)])
    v2 = V.flow([("카메라", MUT), ("Florence-2 단일", G, "한 번 호출·231M·467 GFLOPs"), ("bbox + 768-d 특징", B), ("FM/FiLM 헤드", P, "연속 (lx,ly) 청크 + 속력 규칙"), ("모터", G)])
    diff = tbl(["축", "EGVLA1", "EGVLA2", "측정 상태"], [
        ["인식(백본)", "OWLv2(검출) + Kosmos-2 두 모델", "<b>Florence-2 한 모델</b>이 bbox와 특징을 동시에", f"{st('측정', G)} 젯슨 fp32 1971→817ms(2.41×), 서버 492→180ms(2.73×), 파라미터 458M→231M, GFLOPs 1277→467"],
        ["액션 표현", "8-class 이산(방향 8칸, 속력 고정)", "<b>연속</b>(lx, ly) + 속력 규칙(0.4~0.7, 첫 적용 섀도)", f"{st('측정', G)} 오프라인 R²·방향 오차(CH76-10). 이산→연속 궤적 차이는 ⑤"],
        ["액션 헤드", "MLP", "FM 헤드(A/B2/C): 서브골 조향 + 청크 H=8", f"{st('측정', G)} FM≈MLP 회귀, LOPO에서 C 최우수"],
        ["서브골 조향", "bbox를 입력에 concat", "bbox로 FiLM 조향(B2), 서브골 prefix(C)", f"{st('측정', A)} V6 Stage2 steered 78.41 vs concat 76.76(p=1.6e-5), 연속 타깃에서는 소폭 이득"],
        ["실기 성능", "<b>92.0% (276/300, 실기)</b>", "<b>미측정</b>", f"{st('미착수', R)} EGVLA1은 3 시작 위치(pos1~3)×5 목표 위치×20. <b>EGVLA2는 pos1 하나로 학습</b>해서 비교는 pos1(EGVLA1 95/100)과 pos2·pos3(91, 90)을 따로 보고해야 한다. 8/7 기록 95/100은 pos1 값"],
        ["지연 영향", "젯슨 약 2.0s/프레임", "젯슨 약 0.82s/프레임", f"{st('측정', G)} 지연 중 이동 거리 약 22cm(최대 속력)"]])
    e1 = tbl(["목표 위치(화면상)", "시작 pos1", "시작 pos2(좌 50cm)", "시작 pos3(우 50cm)", "합계"], [
        ["강좌(strong_left)", "19/20", "18/20", "19/20", "56/60 (93%)"], ["약좌(weak_left)", "19/20", "18/20", "19/20", "56/60 (93%)"],
        ["중앙(center)", "20/20", "19/20", "19/20", "58/60 (97%)"], ["약우(weak_right)", "18/20", "20/20", "17/20", "55/60 (92%)"],
        ["강우(strong_right)", "19/20", "16/20", "16/20", "51/60 (85%)"], ["<b>전체</b>", "95/100", "91/100", "90/100", "<b>276/300 (92.0%)</b>"]])
    note = (f'{st("해석 주의", A)} pos1/2/3은 <b>로봇 시작 위치</b>다(pos1 = 2m×2m 맵의 (-1,0) 기본, pos2 = 좌 50cm, pos3 = 우 50cm; 각 100건 = 5 목표 위치×20). 체크포인트 exp73_owl_stage1v3_v6_mlp. '
            'pos2·pos3 수집 중 <b>action_speed_scale 1.0→0.6, stop_on_miss 설정이 바뀌어</b> pos1과 config가 다르다(비교표 각주 필요). 강우가 가장 낮음(85%) — EGVLA2 LOPO(안 본 목표 위치)에서 위치별로 같이 볼 곳.')
    pi = tbl(["π0.7(스터디 노트 기준)", "우리 구현", "같은가?"], [
        ["월드모델이 <b>서브골 이미지</b>를 생성해 정책을 조향", "<b>Florence-2 그라운딩 bbox</b>를 서브골로 사용(이미지 생성 없음)", st("구조 아이디어만 차용", A)],
        ["flow-matching 정책(대형 VLA 위의 action expert)", "경량 FM 헤드: 2층 d=128 AdaLN-Zero 트랜스포머(C), 풀링 특징 1개 + bbox를 prefix로 (Euler 10스텝)", st("π0형 축소판", A)],
        ["시간·조건을 정규화 층에서 주입(AdaLN-Zero 류)", "C: AdaLN-Zero + 청크 토큰 + prefix 어텐션 / B2: FiLM", st("개념 동일, 규모 다름", A)],
        ["연속 매니퓰레이션 데이터로 대규모 학습", "연속 조이스틱 300ep(약 2.9만 프레임, 한 장소)", st("전제 다름", R)],
        ["VLM 백본 공유·대규모 사전학습", "Florence-2는 고정(학습 안 함)·헤드만 학습", st("다름", R)]])
    return (H("⑥-2 EGVLA1 vs EGVLA2 — 무엇이 같고 무엇이 바뀌었나")
            + V.wrap("EGVLA1 (비교 기준, 실기 92.0% = 276/300)", v1, "두 모델을 따로 호출하고 이산 액션을 낸다", kind="flow")
            + V.wrap("EGVLA2 (이번 작업)", v2, "인식을 한 모델로 합치고(지연↓) 액션을 연속·FM으로 바꿈", kind="flow")
            + diff + V.wrap("EGVLA1 실기 스크리닝 상세(276/300)", e1, "출처: 로봇 세션 보고(DATASET_V6_STATUS 기준). 분모 5 목표 위치×3 시작 위치×20", kind="table") + note
            + '<div style="font-size:0.82rem;line-height:1.6;margin:8px 0"><b>Florence-2와 FM 헤드는 서로 다른 축</b>이다. Florence-2는 <b>눈</b>(무엇이 어디 있나: bbox·특징)이고 FM 헤드는 <b>손</b>(그걸 보고 어떻게 움직일까)이다. '
              '지연 절감(2.4×)은 눈을 한 모델로 합쳐서 생겼고, FM 헤드는 지연을 줄이지 않는다(헤드가 추가 연산). FM 헤드의 이유는 연속 액션·서브골 조향이다.</div>'
            + H("FM 헤드는 π0.7에 맞게 적용된 것인가?")
            + pi
            + f'{st("정직한 결론", R)} <b>π0.7을 재현한 것이 아니다.</b> π0.7에서 <b>"서브골이 정책을 조향한다"는 구조 아이디어</b>와 <b>flow-matching + AdaLN-Zero 형태의 헤드</b>를 경량화해 가져온 것이다. '
              '서브골은 생성 이미지가 아니라 검출 bbox이고, 규모·데이터·백본 사전학습이 다르다. 논문에서는 "π0 계열 형태의 경량 헤드", "π0.7의 서브골 조향 아이디어 차용"으로 쓰고 "π0.7 적용"이라고 쓰면 안 된다. 외부 모델 세부(π0.7 구조)는 레포의 스터디 노트(wiki 73-2) 기준이며 원문 대조는 하지 않았다.')
